```javascript
function renderGame() {
  background(135, 206, 235);

  push();
  translate(-width / 2, -height / 2, 0);

  ambientLight(150, 150, 150);
  directionalLight(255, 250, 240, 0.5, 1, -0.5);
  pointLight(255, 255, 200, player.x, player.y, 100);

  // Ground (was Ocean Floor)
  push();
  translate(width / 2, height, -20);
  fill(34, 139, 34);
  ambientMaterial(34, 139, 34);
  box(width * 1.5, 40, 100);
  pop();

  // High Clouds (was Surface Layer)
  push();
  fill(255, 255, 255);
  ambientMaterial(255, 255, 255);
  translate(width / 2, 35, -10);
  box(width * 1.5, 70, 40);
  pop();

  // Tall Trees (was Seaweed)
  fill(139, 69, 19);
  ambientMaterial(139, 69, 19);
  for (let sw of seaweeds) {
    push();
    translate(sw.x, sw.y - sw.h / 2, -10);
    rotateZ(Math.sin(tick * 0.05 + sw.swayOffset) * 0.1);
    cylinder(sw.w, sw.h);

    // Canopy
    push();
    fill(34, 139, 34);
    ambientMaterial(34, 139, 34);
    translate(0, -sw.h / 2, 0);
    cone(sw.w * 3, sw.h / 2);
    pop();
    pop();
  }

  // Background Birds (was Fishes)
  for (let f of bgFishes) {
    push();
    translate(f.x, f.y, f.z);
    let dir = f.vx > 0 ? 0 : PI;
    rotateY(dir);
    fill(f.color[0], f.color[1], f.color[2]);
    ambientMaterial(f.color[0], f.color[1], f.color[2]);
    ellipsoid(8, 4, 4);
    // Wings
    push();
    rotateX(Math.sin(tick * 0.2 + f.x) * 0.5);
    box(4, 1, 16);
    pop();
    pop();
  }

  // Puffy Clouds (was Bubbles)
  fill(255, 255, 255);
  ambientMaterial(255, 255, 255);
  for (let b of bubbles) {
    push();
    translate(b.x + Math.sin(tick * 0.05 + b.seed) * 5, b.y, b.z);
    sphere(b.r * 0.8);
    translate(b.r * 0.5, 0, 0);
    sphere(b.r * 0.5);
    translate(-b.r, 0, 0);
    sphere(b.r * 0.5);
    pop();
  }

  // Oxygen Bar Background
  push();
  fill(20);
  ambientMaterial(20);
  translate(width / 2, height - 10, 5);
  box(width - 20, 10, 5);
  pop();

  // Oxygen Bar Fill
  let oxW = Math.max(0, (player.oxygen / 100) * (width - 20));
  push();
  fill(0, 255, 255);
  ambientMaterial(0, 255, 255);
  translate(10 + oxW / 2, height - 10, 6);
  box(oxW, 8, 6);
  pop();

  // Collected Skydivers Indicators
  fill(255, 100, 0);
  ambientMaterial(255, 100, 0);
  for (let i = 0; i < player.diverCount; i++) {
    push();
    translate(20 + i * 15, 20, 5);
    sphere(4);
    pop();
  }

  // Skydivers (was Divers)
  for (let d of divers) {
    push();
    translate(d.x, d.y, 0);
    let dDir = d.vx > 0 ? 1 : -1;
    rotateY(dDir === 1 ? 0 : PI);

    fill(255, 100, 0);
    ambientMaterial(255, 100, 0);

    // Body
    push();
    rotateZ(HALF_PI);
    cylinder(d.h / 2.5, d.w - 4);
    pop();

    // Head
    push();
    translate(d.w / 2, 0, 0);
    fill(255, 200, 150);
    ambientMaterial(255, 200, 150);
    sphere(d.h / 2.5);
    pop();

    // Parachute Pack
    push();
    fill(40, 200, 40);
    ambientMaterial(40, 200, 40);
    translate(-2, -d.h / 2, -3);
    box(d.w / 2, 4, 6);
    pop();
    pop();
  }

  // Enemies
  for (let e of enemies) {
    push();
    translate(e.x, e.y, 0);
    let dir = e.vx > 0 ? 1 : -1;
    rotateY(dir === 1 ? 0 : PI);

    if (e.type === 'sub') {
      // Plane Enemy
      fill(220, 50, 50);
      specularMaterial(220, 50, 50);
      shininess(30);

      // Body
      push();
      rotateZ(HALF_PI);
      cylinder(e.h / 2, e.w - 6);
      pop();

      // Front cone
      push();
      translate((e.w / 2 - 3), 0, 0);
      rotateZ(-HALF_PI);
      cone(e.h / 2, 8);
      pop();

      // Wings
      push();
      translate(0, 0, 0);
      box(6, 2, e.h * 2.5);
      pop();

      // Tail
      push();
      translate(-(e.w / 2 - 3), -e.h / 2, 0);
      box(4, e.h, 2);
      pop();
    } else {
      // Eagle Enemy
      fill(160, 100, 50);
      specularMaterial(160, 100, 50);
      shininess(10);

      // Body
      ellipsoid(e.w / 2, e.h / 2, e.h / 2);

      // Flapping Wings
      push();
      translate(0, -e.h / 4, 0);
      rotateX(Math.sin(tick * 0.3 + e.x) * 0.5);
      box(e.w / 2, 2, e.h * 3);
      pop();

      // Tail
      push();
      translate(-e.w / 2 - 2, 0, 0);
      box(4, e.h / 2, e.h);
      pop();
    }
    pop();
  }

  // Player Bullets
  fill(255, 255, 0);
  ambientMaterial(255, 255, 0);
  for (let b of pBullets) {
    push();
    translate(b.x, b.y, 0);
    rotateZ(HALF_PI);
    cylinder(2, 6);
    pop();
  }

  // Enemy Bullets
  fill(255, 100, 0);
  ambientMaterial(255, 100, 0);
  for (let b of eBullets) {
    push();
    translate(b.x, b.y, 0);
    rotateZ(HALF_PI);
    cylinder(2, 6);
    pop();
  }

  // Player
  if (gameState === 'PLAYING') {
    push();
    translate(player.x, player.y, 0);
    rotateY(player.facing === 1 ? 0 : PI);

    fill(255, 220, 0);
    specularMaterial(255, 220, 0);
    shininess(40);

    // Airplane Body
    push();
    rotateZ(HALF_PI);
    cylinder(player.h / 2, player.w - 8);
    pop();

    // Front cone
    push();
    translate((player.w / 2 - 4), 0, 0);
    rotateZ(-HALF_PI);
    cone(player.h / 2, 8);
    pop();

    // Back cone
    push();
    translate(-(player.w / 2 - 4), 0, 0);
    rotateZ(-HALF_PI);
    cone(player.h / 2, 8);
    pop();

    // Wings
    push();
    translate(2, 0, 0);
    box(8, 2, player.h * 3);
    pop();

    // Tail fin
    push();
    translate(-(player.w / 2 - 6), -player.h / 2, 0);
    box(6, player.h, 2);
    pop();

    pop();
  }

  pop();
}
```

